static void aa_put_common_ref(struct aa_common_ref *ref)
{
	if (!ref)
		return;

	switch (ref->reftype) {
	case REF_RAWDATA:
		aa_put_i_loaddata(container_of(ref, struct aa_loaddata,
					       count));
		break;
	case REF_PROXY:
